parameters.content:
## LND-WATCHER 2.0 — Report prepartita

Workflow importato **disattivato**.

Prima del test:
1. assegna la credenziale PostgreSQL minima a tutti i nodi Postgres;
2. sostituisci `REPLACE_WITH_TELEGRAM_CHAT_ID` nel nodo **Report Config**;
3. assegna la credenziale Telegram;
4. lascia `telegramEnabled: false` durante lo shadow test.

Il report distingue esplicitamente dati verificati e `NON_VERIFICABILE`.

parameters.jsCode:
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(now);
const get = type => parts.find(p => p.type === type)?.value;
const localDate = [get('year'), get('month'), get('day')].join('-');
const config = {
  workflowVersion: '2.0.0-phase1',
  timezone: 'Europe/Rome',
  telegramEnabled: false,
  telegramChatId: 'REPLACE_WITH_TELEGRAM_CHAT_ID'
};
if (config.telegramEnabled && config.telegramChatId.startsWith('REPLACE_')) {
  throw new Error('Configura telegramChatId prima di abilitare Telegram.');
}
return [{ json: {
  ...config,
  localDate,
  scheduledFor: now.toISOString(),
  runKey: 'lnd-watcher-prematch:' + localDate
}}];

const rows = $input.all().map(item => item.json).filter(row => row.fixture_id);
const cfg = $('Report Config').first().json;
const run = $('Open Report Run').first().json;
if (!rows.length) {
  return [{ json: { hasReport: false, runId: run.id } }];
}
const first = rows[0];
const relevant = rows.filter(row =>
  row.person_id && (
    Number(row.diffide) > 0 ||
    Number(row.suspension_measures) > 0 ||
    Number(row.imposed_gamedays) > 0 ||
    row.residual_gamedays !== null
  )
);
const status = rows.some(row => row.report_data_status === 'NON_VERIFICABILE')
  ? 'NON_VERIFICABILE'
  : 'PARSED';
const time = first.kickoff_time ? String(first.kickoff_time).slice(0, 5) : 'orario non disponibile';
const lines = [
  '⚽ REPORT PREPARTITA — LND-WATCHER 2.0',
  '',
  '**Gara:** ' + first.home_team_name + ' - ' + first.away_team_name,
  '**Data:** ' + first.scheduled_date + ' — ' + time,
  '**Competizione:** ' + first.competition_name + ' (' + first.competition_kind + ')',
  '**Stato dati:** ' + status,
  ''
];
if (!relevant.length) {
  lines.push('Nessun provvedimento ufficiale VERIFIED con saldo disciplinare disponibile per i tesserati registrati.');
} else {
  lines.push('**Situazioni disciplinari VERIFIED:**');
  for (const row of relevant) {
    lines.push(
      '- ' + row.team_name + ' — ' + row.display_name +
      ': diffide ' + Number(row.diffide || 0) +
      ', provvedimenti ' + Number(row.suspension_measures || 0) +
      ', giornate imposte ' + Number(row.imposed_gamedays || 0) +
      ', residue ' + (row.residual_gamedays ?? 'NON_VERIFICABILE')
    );
  }
}
if (status === 'NON_VERIFICABILE') {
  lines.push('', '⚠️ Calendario, identità o dati disciplinari non sono tutti VERIFIED: il report non sostituisce il Comunicato Ufficiale.');
}
const contentMarkdown = lines.join('\n');
return [{ json: {
  hasReport: true,
  runId: run.id,
  fixtureId: first.fixture_id,
  localDate: cfg.localDate,
  contentMarkdown,
  telegramMessage: contentMarkdown.slice(0, 4000),
  verificationStatus: status,
  telegramEnabled: cfg.telegramEnabled,
  telegramChatId: cfg.telegramChatId
}}];

const report = $input.first().json;
const built = $('Build Prematch Report').first().json;
return [{ json: {
  runId: built.runId,
  reportId: report.id,
  telegramMessage: built.telegramMessage,
  telegramEnabled: built.telegramEnabled,
  telegramChatId: built.telegramChatId
}}];
